        <div class="card-title">Card 2</div>
        <div class="card-description">Description for the second card.</div>
      </div>
    </div>

    <!-- Card 3 -->
    <div class="card">
      <div class="card-inner">
        <span class="card-label">Label C</span>
        <div class="card-title">Card 3</div>
        <div class="card-description">Third card description here.</div>
      </div>
    </div>

    <!-- Card 4 -->
    <div class="card">
      <div class="card-inner">
        <span class="card-label">Label D</span>
        <div class="card-title">Card 4</div>
        <div class="card-description">Fourth card description.</div>
      </div>
    </div>

